fn test_example_tools_readme_render_tool_row_0() {
    if !guard_test(
        "test_example_tools_readme_render_tool_row_0",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/readme.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("__out:return".to_string(), Value::Str("mock".to_string()));
    inputs.insert("return".to_string(), Value::Str("mock".to_string()));
    inputs.insert(
        "tool".to_string(),
        Value::Json(serde_json::json!({"mock":true})),
    );
    let outputs = gunbc_exec::execute_single_node(
        &dag,
        "tools.readme::render_tool_row",
        inputs,
        gunbc_exec::ExecutionMode::Real,
    )
    .expect("node 'tools.readme::render_tool_row' should execute successfully");

    // Check output port 'return'
    let output_return = outputs
        .get("return")
        .expect("output port 'return' should exist");
    assert!(
        output_return.as_str().is_some()
            || matches!(*output_return, Value::Skipped | Value::Secret(_)),
        "expected String, Secret, or Skipped for output_return"
    );
}

