// =========================================================================
// RV-4: Failure Variant Tests
// =========================================================================

// Each test replaces one transport boundary mock with a failure response
// (e.g., shell exit 1, REST 401/500, file not found) and verifies that
// DryRun execution completes without panicking.

/// Failure variant: execute_readme_transport_rest_401_auth.
///
/// Verifies that the DAG handles a transport failure without panicking.
/// One transport boundary is replaced with a failure response while all
/// other boundaries keep their success values.
#[test]
fn test_failure_execute_readme_transport_rest_401_auth() {
    if !guard_test(
        "test_failure_execute_readme_transport_rest_401_auth",
        TestClass::Unit,
        FermiCost::XS,
        &[],
        &[],
    ) {
        return;
    };
    let dag = gunbc_resolve::builder::build_dsl_graph_dag(
        "tools/readme.dag",
        gunbc_resolve::BuildOpts::default(),
    )
    .expect("graph should build");
    let spec = mock_spec();
    let variants = gunbc_test::auto_mock_failure_variants(&spec);
    let variant = variants
        .iter()
        .find(|v| v.tag == "execute_readme_transport_rest_401_auth")
        .expect("failure variant 'execute_readme_transport_rest_401_auth' should exist");
    let mocks = variant.spec.to_boundary_mocks();
    let _result = execute_dag(
        &dag,
        ExecuteConfig {
            mode: ExecutionMode::DryRun(mocks),
            ..Default::default()
        },
    );
    // Failure variant: execution completes without panic (errors are acceptable)
}

